export interface HomeLayer {
  id: string;
  name: string;
  /** Lucide icon name, rendered through `IGRPIcon`. */
  icon: string;
  /** What this layer did for the current request, in plain words. */
  value: string;
  detail: string;
  /** Where to change it. */
  file: string;
  state: HomeLayerState;
}

export interface HomeOverviewProps {
  appName: string;
  appCode: string;
  version: string;
  previewMode: boolean;
